#pragma once
#include <stdint.h>

// Bitmap fonts (4-bit alpha). Generated by tools/gen_fonts.py from Barlow (SIL OFL 1.1).
// Text fonts cover ASCII + Latin accents (pt/es/fr) + typographic punctuation; digit fonts only digits.

struct Glyph {
  uint16_t cp;      // Unicode code point
  uint8_t w, h;     // bitmap size
  int16_t xoff;     // offset from the pen origin
  int16_t yoff;     // offset from the top of the line
  int16_t adv;      // horizontal advance
  uint32_t offset;  // start in the bit array (4 bpp, 2 px per byte)
};

struct Font {
  const Glyph* glyphs;
  uint16_t count;
  const uint8_t* bits;
  int16_t ascent, descent;
};

extern const Font FONT_LIFE;   // condensed digits, 108 px
extern const Font FONT_HUGE;   // condensed digits, 210 px
extern const Font FONT_TINY;   // condensed digits, 22 px
extern const Font FONT_BIG;    // condensed, 64 px — big titles
extern const Font FONT_MED;    // semibold, 30 px — page titles, buttons
extern const Font FONT_SMALL;  // medium, 22 px
extern const Font FONT_CLOCK;  // condensed digits and ":", 70 px
extern const Font FONT_TEMP;   // condensed digits and "°", 50 px
extern const Font FONT_COND;   // condensed, 28 px — numbers, short labels
extern const Font FONT_HEAD;   // semibold, 21 px — headlines
extern const Font FONT_BODY;   // medium, 16 px — body text
extern const Font FONT_CAP;    // semibold, 13 px — captions
extern const Font FONT_MINI;   // semibold, 11 px — tiny labels
extern const Font FONT_WATCH;  // condensed digits and ":", 150 px — full-screen clock
extern const Font FONT_TITLE;  // semibold, 36 px — rich text title
extern const Font FONT_TXT;    // medium, 24 px — rich text regular
extern const Font FONT_TXT_B;  // semibold, 24 px — rich text bold
extern const Font FONT_TXT_I;  // medium, 24 px, slanted — rich text italic
